// === Tab: GoL ===
let grid,
		nextGrid,
		mballs,
		cols,
		rows;

const live = [2, 3],
		  born = [3],
			cellSize = 35,
			neighbors = [];

function setup() {
	cols = ~~(windowWidth/cellSize);
	rows = ~~(windowHeight/cellSize);

	createCanvas(windowWidth, windowHeight, WEBGL);
	shader(metaballShader);

	grid = Array(cols * rows);
	mballs = Array(cols * rows);
	nextGrid = Array(cols * rows);

	const indexOf = (x, y) => (y < 0 ? rows + y : y % rows) * cols + (x < 0 ? cols + x : x % cols);

	for (let i = 0; i < grid.length; i ++) {
		grid[i] = Math.random() < 0.5;

		const x = i % cols,
					y = Math.floor(i / cols);

		neighbors[i] = [
			indexOf(x - 1, y - 1),
			indexOf(x    , y - 1),
			indexOf(x + 1, y - 1),
			indexOf(x - 1, y    ),
			indexOf(x + 1, y    ),
			indexOf(x - 1, y + 1),
			indexOf(x    , y + 1),
			indexOf(x + 1, y + 1)
		];
	}
}

function draw() {
	for (let i = 0; i < grid.length; i ++) {
		adj = 0;
		for (let k of neighbors[i]) {
			if (grid[k]) adj ++;
		}

		if(grid[i] && !live.includes(adj)) nextGrid[i] = false;
		else if(!grid[i] && born.includes(adj)) nextGrid[i] = true;
		else nextGrid[i] = grid[i];
	}

	const temp = grid;
	grid = nextGrid;
	nextGrid = temp;

	for(let i = 0; i < grid.length; i ++) {
		if (grid[i]) {
			if(mballs[i] && mballs[i][2] < cellSize / 1.5)
				mballs[i][2] ++;
			else if (!mballs[i])
				mballs[i] = [i % cols * cellSize, Math.floor(i / cols) * cellSize, cellSize / 4]
		} else if(mballs[i]){
			mballs[i][2] --;
			if(mballs[i][2] < 0) mballs[i] = null
		}
	}

	let metaballs = [];
	for(let i of mballs){
		if(i) metaballs.push(...i);
	}
	metaballShader.setUniform("metaballs", metaballs);
	metaballShader.setUniform("N_balls", metaballs.length);
	rect(0, 0, width, height);
}

// === Tab: shader ===
let metaballShader;

function preload() {
	metaballShader = getShader(this._renderer);
}

function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 metaballs[500];
		uniform mediump int N_balls;

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			for (int i = 0; i < 100000; i++) {
				if(i >= N_balls){break;}
				vec3 ball = metaballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				float r = ball.z;
				v += r * r / (dx * dx + dy * dy);
			}

			if (v > 1.0) gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
			else gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
		}
	`;

	return createShader(vert, frag);
}

